namespace moon {
std::vector<std::string> Document::layerMoveTargets()const{return layerMove_?layerMove_->celIds:std::vector<std::string>{};}
bool Document::beginLayerMove(const std::vector<std::string>& ids,bool duplicate,std::optional<TransformPoint> pivot){if(hasTilemapContent()||hasFreeTileContent())return false;
 if(layerMove_)return false;if(!activeMaskId_.empty()){commitFloatingPaste();if(active()||!maskBrushAvailable())return false;LayerMovePreview move;move.edit=Edit{{},state_,nextState_};move.edit.beforeMasks=timeline_.state().masks;layerMove_=std::move(move);return true;}commitFloatingPaste();if(active())return false;LayerMovePreview move;move.edit=Edit{{},state_,nextState_};auto& e=move.edit;e.beforeActive=e.afterActive=activeLayerId_;e.beforeFrame=e.afterFrame=activeFrameId_;e.beforeTimelineSelection=e.afterTimelineSelection=timelineSelection_;e.beforeSelection=e.afterSelection=selectedFrames_;e.pixelSelectionEdit=true;e.beforePixelsSelection=e.afterPixelsSelection=selection_;e.beforeTrimPivot.emplace(pivot);e.afterTrimPivot.emplace(pivot);
 std::unordered_set<std::string> owners,layers;
 for(const auto& id:ids){const auto* c=timeline_.findCelById(id);if(!c||!timeline_.hasLayer(c->layerId))continue;const auto& l=timeline_.state().layers[timeline_.layerIndex(c->layerId)];if(!layerEffectivelyVisible(l)||layerEffectivelyLocked(l))continue;const auto r=timeline_.resolveSurface(id);if(r.issue!=timeline::LinkIssue::None||!r.source||!r.surface)continue;move.celIds.push_back(id);layers.insert(c->layerId);if(!owners.insert(r.source->id).second)continue;const auto& s=*r.surface;raster::validate(s);e.ownerOffsets.push_back({r.source->id,s.offsetX,s.offsetY,s.offsetX,s.offsetY});move.bounds.push_back({s.offsetX,s.offsetY,s.width,s.height});if(r.source->text)e.textChanges.push_back({r.source->id,r.source->text,r.source->text});}
 if(!timeline_.state().masks.empty())e.beforeMasks=timeline_.state().masks;
 if(e.ownerOffsets.empty())return false;move.duplicate=duplicate&&layers.size()==1&&move.celIds.size()<=1;if(move.duplicate){if(timeline_.state().layers.size()>=256)return false;std::size_t used=0;constexpr std::size_t limit=256*1024*1024;for(const auto& c:timeline_.state().cels)if(c.surface){const auto count=c.surface->pixels.size();const auto multiplier=layers.count(c.layerId)?3u:1u;if(count>(limit-used)/(sizeof(Pixel)*multiplier))return false;used+=count*sizeof(Pixel)*multiplier;}captureGroupEdit(e,false);}layerMove_=std::move(move);return true;
}
bool Document::previewLayerMove(int dx,int dy){
 if(!layerMove_)return false;auto& move=*layerMove_;if(move.x==dx&&move.y==dy)return true;
 if(move.edit.beforeMasks){const auto& baseline=*move.edit.beforeMasks;std::set<std::string> maskIds;if(!activeMaskId_.empty())maskIds.insert(activeMaskId_);else for(const auto& key:move.celIds){const auto* cel=timeline_.findCelById(key);if(!cel)continue;for(const auto& slot:baseline)if(slot.frameId==cel->frameId){const auto* boundMask=timeline::resolvedMask(timeline_.state(),slot.ownerId,slot.frameId);if(!boundMask||!boundMask->moveWithOwner)continue;bool selected=!slot.group&&slot.ownerId==cel->layerId;if(slot.group){auto groupId=std::optional<std::string>(slot.ownerId);std::set<std::string> seen;while(groupId&&seen.insert(*groupId).second){if(std::find(selectedGroupIds_.begin(),selectedGroupIds_.end(),*groupId)!=selectedGroupIds_.end()||selectedGroupId_==groupId){selected=true;break;}const auto* group=findGroup(*groupId);groupId=group?group->parentGroupId:std::optional<std::string>{};}}if(selected){const auto* mask=timeline::resolvedMask(timeline_.state(),slot.ownerId,slot.frameId);if(mask)maskIds.insert(mask->id);}}}for(auto& slot:timeline_.state_.masks)if(maskIds.count(slot.mask.id)){const auto it=std::find_if(baseline.begin(),baseline.end(),[&](const auto& b){return b.mask.id==slot.mask.id;});if(it==baseline.end())continue;slot.mask.surface.offsetX=raster::coordinate(std::int64_t(it->mask.surface.offsetX)+dx);slot.mask.surface.offsetY=raster::coordinate(std::int64_t(it->mask.surface.offsetY)+dy);}move.edit.afterMasks=timeline_.state().masks;}
 if(move.duplicated&&!move.celIds.empty()){const auto* cel=timeline_.findCelById(move.celIds.front());if(cel)for(auto& slot:timeline_.state_.masks)if(slot.ownerId==cel->layerId&&slot.mask.moveWithOwner){slot.mask.surface.offsetX=raster::coordinate(std::int64_t(slot.mask.surface.offsetX)+dx-move.x);slot.mask.surface.offsetY=raster::coordinate(std::int64_t(slot.mask.surface.offsetY)+dy-move.y);}}
 // Validate every placement before changing any owner. Pixels stay in their existing storage.
 for(const auto& o:move.edit.ownerOffsets){const auto r=timeline_.resolveSurface(o.ownerId);if(!r.source||!r.surface)return false;const auto x=std::int64_t(o.beforeX)+dx,y=std::int64_t(o.beforeY)+dy;raster::coordinate(x);raster::coordinate(y);raster::coordinate(x+r.surface->width);raster::coordinate(y+r.surface->height);}
 if(move.edit.beforePixelsSelection){raster::coordinate(std::int64_t(move.edit.beforePixelsSelection->x)+dx);raster::coordinate(std::int64_t(move.edit.beforePixelsSelection->y)+dy);}
 if(move.duplicate&&!move.duplicated&&(dx||dy)){
  const auto sourceLayer=timeline_.findCelById(move.celIds.front())->layerId;const auto original=timeline_.state().layers[timeline_.layerIndex(sourceLayer)];auto copy=original;do{copy.id="layer-native-"+std::to_string(identity_)+"-"+std::to_string(++nextLayerId_);}while(timeline_.hasLayer(copy.id));copy.name+=U" 副本";const auto at=timeline_.layerIndex(sourceLayer)+1;auto& state=timeline_.state_;std::vector<DocumentCel> copies;std::unordered_map<std::string,std::string> translated;
  for(const auto& c:state.cels)if(c.layerId==sourceLayer){auto item=c;item.id=copy.id+"-"+c.frameId;item.layerId=copy.id;translated[c.id]=item.id;copies.push_back(std::move(item));}
  for(auto& c:copies){if(c.linkedCelId){const auto it=translated.find(*c.linkedCelId);if(it==translated.end())throw std::invalid_argument("Cross-layer cel link cannot be copied");c.linkedCelId=it->second;}if(c.runtimeSharedCelId){const auto it=translated.find(*c.runtimeSharedCelId);if(it!=translated.end())c.runtimeSharedCelId=it->second;else{const auto r=timeline_.resolveSurface(c.id);if(r.surface)c.surface=*r.surface;c.runtimeSharedCelId.reset();}}}
  if(move.edit.beforeMasks){state.masks=*move.edit.beforeMasks;for(const auto& slot:*move.edit.beforeMasks)if(!slot.group&&slot.ownerId==sourceLayer){auto m=slot;m.ownerId=copy.id;m.mask.id="mask-native-"+std::to_string(identity_)+"-"+std::to_string(++nextLayerId_);const auto* resolved=timeline::resolvedMask(state,slot.ownerId,slot.frameId);m.mask.surface=resolved->surface;m.mask.linkedMaskId.clear();m.mask.surface.offsetX=raster::coordinate(std::int64_t(m.mask.surface.offsetX)+dx);m.mask.surface.offsetY=raster::coordinate(std::int64_t(m.mask.surface.offsetY)+dy);state.masks.push_back(std::move(m));}}state.layers.insert(state.layers.begin()+at,copy);for(auto& c:copies)state.cels.push_back(std::move(c));timeline_.buildIndex();move.edit.ownerOffsets.clear();move.edit.textChanges.clear();move.bounds.clear();move.celIds.clear();for(const auto& c:state.cels)if(c.layerId==copy.id){move.celIds.push_back(c.id);if(c.surface){move.edit.ownerOffsets.push_back({c.id,c.surface->offsetX,c.surface->offsetY,c.surface->offsetX,c.surface->offsetY});move.bounds.push_back({c.surface->offsetX,c.surface->offsetY,c.surface->width,c.surface->height});if(c.text)move.edit.textChanges.push_back({c.id,c.text,c.text});}}
  activeLayerId_=copy.id;timelineSelection_.layers={copy.id};timelineSelection_.cels.clear();timelineSelection_.layerAnchor=copy.id;selectedGroupIds_.clear();selectedGroupId_.reset();move.duplicated=true;
 }
 for(auto& change:move.edit.textChanges){auto data=*change.before;translateTextCelData(data,dx,dy);change.after=data;timeline_.state_.cels[timeline_.cels_.at(change.id)].text=data;}
 change_={};if(move.edit.beforeMasks)change_={0,0,width_,height_};for(std::size_t i=0;i<move.edit.ownerOffsets.size();++i){auto& o=move.edit.ownerOffsets[i];auto& c=timeline_.state_.cels[timeline_.cels_.at(o.ownerId)];auto& s=*c.surface;auto dirty=[&](int x,int y){const auto left=std::max<std::int64_t>(0,x),top=std::max<std::int64_t>(0,y),right=std::min<std::int64_t>(width_,std::int64_t(x)+s.width),bottom=std::min<std::int64_t>(height_,std::int64_t(y)+s.height);if(right>left&&bottom>top){change_.include(int(left),int(top));change_.include(int(right-1),int(bottom-1));}};dirty(s.offsetX,s.offsetY);s.offsetX=o.beforeX+dx;s.offsetY=o.beforeY+dy;o.afterX=s.offsetX;o.afterY=s.offsetY;dirty(s.offsetX,s.offsetY);}
 if(move.edit.beforePixelsSelection){auto selected=*move.edit.beforePixelsSelection;selected.x=raster::coordinate(std::int64_t(selected.x)+dx);selected.y=raster::coordinate(std::int64_t(selected.y)+dy);selection_=std::move(selected);}if(move.edit.beforeTrimPivot&&*move.edit.beforeTrimPivot){auto pivot=**move.edit.beforeTrimPivot;pivot.x+=dx;pivot.y+=dy;move.edit.afterTrimPivot.emplace(pivot);}move.x=dx;move.y=dy;publishChange();return true;
}
void Document::cancelLayerMove(){if(!layerMove_)return;auto move=std::move(*layerMove_);layerMove_.reset();if(move.edit.beforeMasks)timeline_.state_.masks=*move.edit.beforeMasks;for(const auto& change:move.edit.textChanges)if(timeline_.cels_.count(change.id))timeline_.state_.cels[timeline_.cels_.at(change.id)].text=change.before;for(const auto& o:move.edit.ownerOffsets)if(const auto r=timeline_.resolveSurface(o.ownerId);r.source&&r.source->id==o.ownerId&&r.surface){auto& s=*timeline_.state_.cels[timeline_.cels_.at(o.ownerId)].surface;s.offsetX=o.beforeX;s.offsetY=o.beforeY;}if(move.duplicated){captureGroupEdit(move.edit,true);applyLayerStructure(move.edit,false);applyGroupUi(move.edit,false);timelineSelection_=*move.edit.beforeTimelineSelection;selectedFrames_=*move.edit.beforeSelection;}selection_=move.edit.beforePixelsSelection;change_={0,0,width_,height_};publishChange();}
bool Document::commitLayerMove(){if(!layerMove_)return false;if(!layerMove_->x&&!layerMove_->y&&!layerMove_->duplicated){cancelLayerMove();return false;}auto move=std::move(*layerMove_);layerMove_.reset();auto& e=move.edit;if(e.beforeMasks)e.afterMasks=timeline_.state().masks;e.afterPixelsSelection=selection_;if(move.duplicated){captureGroupEdit(e,true);e.ownerOffsets.clear();e.textChanges.clear();for(const auto& c:timeline_.state().cels)if(c.layerId==activeLayerId_)e.structureCelBytes+=sizeof(c)+(c.surface?c.surface->pixels.size()*sizeof(Pixel):0);}history_.reserve(position_+1);pushEdit(std::move(e),move.duplicated?U"复制图层":move.celIds.size()>1?U"移动多个图层":U"移动图层");return true;}
}
